// ---- content/tri.js ----
// Тема «Треугольники»: углы и стороны, равенство, подобие, замечательные линии, прямоугольный треугольник,
// дополнительные построения. Чертежи строятся через MM.fig (content/_fig.js).
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function sq(x) { return '<span class="sq">√<span>' + x + '</span></span>'; }
  const F = MM.fig, s1 = 'A<sub>1</sub>', b1 = 'B<sub>1</sub>';

  // чертежи уроков
  const figL1 = F({ pts: { A: [0, 0], B: [6, 0], C: [2, 3.5], D: [3.2, 5.6] }, poly: ['ABC'], dash: ['CD'], ang: [['B', 'A', 'C'], ['C', 'B', 'A', 2], ['B', 'C', 'D', 3]], hide: [], lab: { D: 'ne' }, alt: 'Треугольник ABC, сторона AC продолжена за точку C до точки D; отмечен внешний угол BCD' });
  const figL2 = F({ pts: { A: [0, 4], B: [-3, 0], C: [3, 0], M: [0, 0] }, poly: ['ABC'], seg: ['AM'], ticks: { AB: 1, AC: 1, BM: 2, MC: 2 }, right: [['A', 'M', 'C']], ang: [['B', 'A', 'M'], ['M', 'A', 'C']], lab: { M: 's' }, alt: 'Равнобедренный треугольник ABC с медианой AM, которая перпендикулярна основанию' });
  const figL3 = F({ pts: { A: [0, 0], C: [5, 0], B: [1.5, 4], M: [0.6, 1.6], N: [3.6, 1.6] }, poly: ['ABC'], gold: ['MN'], lab: { M: 'w', N: 'e' }, alt: 'Треугольник ABC, отрезок MN параллелен стороне AC' });
  const figL4 = F({ pts: { A: [0, 0], B: [6, 0], C: [2, 4.5], A1: [4, 2.25], B1: [1, 2.25], C1: [3, 0], G: [8 / 3, 1.5] }, poly: ['ABC'], dash: [['A', 'A1'], ['B', 'B1'], ['C', 'C1']], lab: { G: 'se', C1: 's', A1: 'ne', B1: 'nw' }, alt: 'Треугольник ABC с тремя медианами, пересекающимися в точке G' });
  const figL5 = F({ pts: { A: [0, 0], B: [5, 0], C: [1.8, 2.4], H: [1.8, 0] }, poly: ['ABC'], seg: ['CH'], right: [['A', 'C', 'B'], ['C', 'H', 'B']], lab: { H: 's' }, alt: 'Прямоугольный треугольник ABC с прямым углом C и высотой CH к гипотенузе' });
  const figL6 = F({ pts: { A: [2, 4], B: [0, 0], C: [6, 0], M: [3, 0], D: [4, -4] }, poly: ['ABC'], seg: ['AM'], dash: ['MD', 'BD', 'CD'], ticks: { AM: 1, MD: 1 }, lab: { M: 'se', D: 'se' }, alt: 'Медиана AM удвоена до точки D; получен параллелограмм ABDC' });

  // чертежи задач
  const fig11 = F({ pts: { B: [0, 0], C: [10, 0], A: [2.75, 5.333], D: [4, 0] }, poly: ['ABC'], seg: ['AD'], ang: [['B', 'A', 'D'], ['D', 'A', 'C']], len: { AB: '6', AC: '9' }, lab: { D: 's' }, w: 280, alt: 'Треугольник ABC с биссектрисой AD' });
  const fig12 = F({ pts: { A: [0, 0], C: [6, 0], B: [2, 4.5], M: [1.2, 2.7], N: [3.6, 2.7] }, poly: ['ABC'], gold: ['MN'], lab: { M: 'w', N: 'e' }, w: 260, alt: 'Треугольник ABC, отрезок MN параллелен AC' });
  const fig17 = F({ pts: { A: [0, 0], C: [2, 0], B: [1, 2.3559], D: [1.3893, 1.4387] }, poly: ['ABC'], seg: ['AD'], ticks: { AB: 1, BC: 1 }, ang: [['B', 'A', 'D']], lab: { D: 'e' }, w: 220, alt: 'Равнобедренный треугольник ABC с AB = BC и отрезок AD к стороне BC' });
  const fig21 = F({ pts: { A: [0, 0], B: [9, 0], H: [4, 0], C: [4, 4.472] }, poly: ['ABC'], seg: ['CH'], right: [['A', 'C', 'B'], ['C', 'H', 'B']], len: { AH: '4', AC: '6' }, lab: { H: 's' }, w: 280, alt: 'Прямоугольный треугольник ABC с высотой CH' });
  const fig24 = F({ pts: { A: [0, 0], B: [6, 0], C: [2, 4.5], A1: [4, 2.25], B1: [1, 2.25], M: [8 / 3, 1.5] }, poly: [{ p: ['A1', 'M', 'B1', 'C'], fill: true }, 'ABC'], seg: [['A', 'A1'], ['B', 'B1']], lab: { M: 's', A1: 'ne', B1: 'nw' }, w: 280, alt: 'Треугольник ABC, медианы AA1 и BB1, закрашен четырёхугольник A1MB1C' });
  const fig25 = F({ pts: { A: [0, 0], C: [9, 0], B: [2.909, 5.248], D: [4, 0] }, poly: ['ABC'], seg: ['BD'], ang: [['A', 'B', 'D'], ['B', 'C', 'A']], len: { AB: '6' }, lab: { D: 's' }, w: 280, alt: 'Треугольник ABC, точка D на AC, отмечены равные углы ABD и ACB' });
  const fig36 = F({ pts: { B: [0, 0], A: [2, 0], C: [-0.468, 1.2856], M: [0.766, 0.6428] }, poly: ['ABC'], seg: ['BM'], ang: [['A', 'B', 'M']], lab: { M: 'ne' }, w: 240, alt: 'Треугольник ABC с медианой BM' });

  MM.addTopic({
    id: 'tri',
    sec: 'geo',
    title: 'Треугольники',
    blurb: `Углы и стороны, признаки равенства и подобия, медианы, биссектрисы и высоты, прямоугольный треугольник и дополнительные построения. Основа всей олимпиадной геометрии.`,

    lessons: [
      { id: 'tri-l1', title: 'Углы и стороны треугольника', mins: 10, html: `
<div class="box"><div class="box-h">Запомни</div><ul>
<li>Сумма углов треугольника равна <span class="m">180°</span>.</li>
<li><b>Внешний угол</b> равен сумме двух внутренних углов, не смежных с ним.</li>
<li>В равнобедренном треугольнике углы при основании равны. И обратно: если два угла равны, треугольник равнобедренный.</li>
<li>Против большей стороны лежит больший угол, против большего угла — большая сторона.</li>
<li><b>Неравенство треугольника:</b> каждая сторона меньше суммы двух других и больше их разности.</li>
</ul></div>
${figL1}
<p>На чертеже <span class="m">∠BCD</span> — внешний угол при вершине <span class="m">C</span>. Он дополняет <span class="m">∠ACB</span> до <span class="m">180°</span>, и столько же дают <span class="m">∠A + ∠B</span>. Поэтому <span class="m">∠BCD = ∠A + ∠B</span>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Две стороны треугольника равны 2 и 5. Какой может быть третья сторона, если она — целое число?</p>
<p><b>Решение.</b> <span class="m">5 − 2 < c < 5 + 2</span>, то есть <span class="m">3 < c < 7</span>: <span class="m">c = 4, 5, 6</span>. При <span class="m">c = 3</span> или <span class="m">c = 7</span> «треугольник» вырождается в отрезок.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Неравенство треугольника — главный инструмент в задачах «докажите, что отрезок меньше». Ищи треугольник, в котором нужный отрезок — одна сторона, а две другие уже известны.</p></div>` },

      { id: 'tri-l2', title: 'Равенство треугольников', mins: 12, html: `
<div class="box"><div class="box-h">Признаки равенства</div><ol>
<li>По двум сторонам и углу между ними.</li>
<li>По стороне и двум прилежащим к ней углам.</li>
<li>По трём сторонам.</li>
<li>Для прямоугольных треугольников ещё и по гипотенузе и катету, по гипотенузе и острому углу.</li>
</ol></div>
<p>Почти любое доказательство равенства отрезков или углов в простых задачах устроено так: найти два треугольника, в которые эти отрезки или углы входят, и доказать, что треугольники равны.</p>
${figL2}
<div class="ex"><div class="ex-h">Пример</div>
<p>Докажите, что в равнобедренном треугольнике медиана, проведённая к основанию, является и биссектрисой, и высотой.</p>
<p><b>Решение.</b> Пусть <span class="m">AB = AC</span>, <span class="m">M</span> — середина <span class="m">BC</span>. Треугольники <span class="m">ABM</span> и <span class="m">ACM</span> равны по трём сторонам: <span class="m">AB = AC</span>, <span class="m">BM = MC</span>, <span class="m">AM</span> — общая. Значит, <span class="m">∠BAM = ∠CAM</span> (биссектриса) и <span class="m">∠AMB = ∠AMC</span>. Эти углы смежные, поэтому каждый равен <span class="m">90°</span> (высота).</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Если нужных треугольников на чертеже нет — построй их: продли отрезок, отложи равный, проведи параллельную. Об этом — последний урок темы.</p></div>` },

      { id: 'tri-l3', title: 'Подобие треугольников', mins: 12, html: `
<p>Треугольники <b>подобны</b>, если их углы соответственно равны, а стороны пропорциональны: <span class="m">${fr('A′B′', 'AB')} = ${fr('B′C′', 'BC')} = ${fr('C′A′', 'CA')} = k</span>. Число <span class="m">k</span> — коэффициент подобия.</p>
<div class="box"><div class="box-h">Признаки подобия</div><ol>
<li>По двум углам.</li>
<li>По двум пропорциональным сторонам и углу между ними.</li>
<li>По трём пропорциональным сторонам.</li>
</ol>
<p>Периметры подобных треугольников относятся как <span class="m">k</span>, а площади — как <span class="m">k<sup>2</sup></span>.</p></div>
${figL3}
<p>Прямая, параллельная стороне треугольника, отсекает от него треугольник, подобный исходному: на чертеже <span class="m">MN ∥ AC</span>, и треугольники <span class="m">MBN</span> и <span class="m">ABC</span> подобны по двум углам.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>На чертеже <span class="m">BM = 3</span>, <span class="m">MA = 2</span>, <span class="m">AC = 10</span>. Найдите <span class="m">MN</span>.</p>
<p><b>Решение.</b> Коэффициент подобия <span class="m">k = ${fr('BM', 'BA')} = ${fr('3', '5')}</span>, поэтому <span class="m">MN = ${fr('3', '5')} · 10 = 6</span>.</p></div>
<h3>Средняя линия</h3>
<p>Отрезок, соединяющий середины двух сторон, параллелен третьей стороне и равен её половине. Это частный случай подобия с <span class="m">k = ${fr('1', '2')}</span>.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь отношение отрезков — ищи подобные треугольники. Чаще всего их дают параллельные прямые или общий угол плюс ещё одна пара равных углов.</p></div>` },

      { id: 'tri-l4', title: 'Замечательные линии и точки', mins: 14, html: `
${figL4}
<div class="box"><div class="box-h">Четыре замечательные точки</div><ul>
<li><b>Медианы</b> пересекаются в одной точке <span class="m">G</span> (центр тяжести) и делятся ею в отношении <span class="m">2 : 1</span>, считая от вершины.</li>
<li><b>Биссектрисы</b> пересекаются в центре <span class="m">I</span> вписанной окружности.</li>
<li><b>Высоты</b> (или их продолжения) пересекаются в ортоцентре <span class="m">H</span>.</li>
<li><b>Серединные перпендикуляры</b> к сторонам пересекаются в центре <span class="m">O</span> описанной окружности.</li>
</ul></div>
<h3>Медианы и площади</h3>
<p>Медиана делит треугольник на два треугольника равной площади: у них равные основания и общая высота. Три медианы делят треугольник на <b>шесть</b> треугольников равной площади.</p>
<h3>Свойство биссектрисы</h3>
<p>Биссектриса <span class="m">AD</span> делит противоположную сторону в отношении прилежащих сторон:</p>
<p class="calc"><span class="m">${fr('BD', 'DC')} = ${fr('AB', 'AC')}</span>.</p>
<h3>Угол между биссектрисами</h3>
<p>Если <span class="m">I</span> — точка пересечения биссектрис, то <span class="m">∠BIC = 90° + ${fr('1', '2')}∠A</span>. Действительно, <span class="m">∠IBC + ∠ICB = ${fr('1', '2')}(∠B + ∠C) = ${fr('1', '2')}(180° − ∠A)</span>, и <span class="m">∠BIC</span> дополняет эту сумму до <span class="m">180°</span>.</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Отношение 2 : 1 для медиан и формула для биссектрисы — самые частые «готовые факты» на этапах олимпиады. Но на финале их тоже нужно уметь доказывать: это задачи этой темы.</p></div>` },

      { id: 'tri-l5', title: 'Прямоугольный треугольник', mins: 12, html: `
<div class="box"><div class="box-h">Запомни</div><ul>
<li><b>Теорема Пифагора:</b> <span class="m">a<sup>2</sup> + b<sup>2</sup> = c<sup>2</sup></span>, где <span class="m">c</span> — гипотенуза. Верна и обратная теорема.</li>
<li>Пифагоровы тройки: <span class="m">3, 4, 5</span>; <span class="m">5, 12, 13</span>; <span class="m">8, 15, 17</span>; <span class="m">7, 24, 25</span> и кратные им.</li>
<li>Медиана к гипотенузе равна её половине; центр описанной окружности — середина гипотенузы.</li>
<li>Катет против угла <span class="m">30°</span> равен половине гипотенузы.</li>
<li>Радиус вписанной окружности: <span class="m">r = ${fr('a + b − c', '2')}</span>.</li>
</ul></div>
${figL5}
<h3>Высота к гипотенузе</h3>
<p>Высота <span class="m">CH</span> делит прямоугольный треугольник на два, подобных исходному. Отсюда, если <span class="m">AH = p</span>, <span class="m">HB = q</span>:</p>
<p class="calc"><span class="m">CH<sup>2</sup> = pq</span>, <span class="m">AC<sup>2</sup> = p · c</span>, <span class="m">BC<sup>2</sup> = q · c</span>, <span class="m">CH = ${fr('ab', 'c')}</span>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Катеты равны 3 и 4. Тогда гипотенуза 5, высота к ней <span class="m">${fr('3 · 4', '5')} = ${fr('12', '5')}</span>, отрезок <span class="m">AH = ${fr('3<sup>2</sup>', '5')} = ${fr('9', '5')}</span>, а радиус вписанной окружности <span class="m">${fr('3 + 4 − 5', '2')} = 1</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь прямой угол — ищи высоту к гипотенузе и три подобных треугольника. Площадь прямоугольного треугольника удобно считать двумя способами: <span class="m">${fr('ab', '2')} = ${fr('c · h', '2')}</span>.</p></div>` },

      { id: 'tri-l6', title: 'Дополнительные построения и счёт углов', mins: 12, html: `
<p>Во многих задачах решение появляется, только когда на чертеже добавлена одна линия. Вот самые частые построения.</p>
<h3>Удвоение медианы</h3>
${figL6}
<p>Отложим на продолжении медианы <span class="m">AM</span> отрезок <span class="m">MD = AM</span>. Диагонали <span class="m">AD</span> и <span class="m">BC</span> четырёхугольника <span class="m">ABDC</span> делятся точкой <span class="m">M</span> пополам, значит, это параллелограмм: <span class="m">BD = AC</span>, <span class="m">CD = AB</span>, <span class="m">BD ∥ AC</span>. Медиана превращается в половину диагонали, а стороны треугольника — в стороны параллелограмма.</p>
<h3>Параллельная прямая</h3>
<p>Проведи через вершину прямую, параллельную стороне или биссектрисе: появятся равные накрест лежащие и соответственные углы, а с ними — равнобедренные и подобные треугольники.</p>
<h3>Счёт углов</h3>
<p>Обозначь неизвестный угол буквой, например <span class="m">α</span>, и выражай через неё все остальные: сумма углов треугольника, углы при основании равнобедренного, внешний угол. В конце получится уравнение.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>В треугольнике <span class="m">ABC</span> медиана <span class="m">CM</span> равна половине стороны <span class="m">AB</span>. Докажите, что <span class="m">∠C = 90°</span>.</p>
<p><b>Решение.</b> <span class="m">MA = MB = MC</span>, поэтому треугольники <span class="m">AMC</span> и <span class="m">BMC</span> равнобедренные: <span class="m">∠MCA = ∠A</span>, <span class="m">∠MCB = ∠B</span>. Значит, <span class="m">∠C = ∠A + ∠B</span>, а так как <span class="m">∠A + ∠B + ∠C = 180°</span>, то <span class="m">∠C = 90°</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Медиана в условии — пробуй удвоить её. Биссектриса — отрази относительно неё или проведи параллельную. Равные отрезки, которые никак не связаны, — достраивай равнобедренный треугольник.</p></div>` }
    ],

    problems: [
      // Уровень 1
      { id: 'tri-01', lvl: 1, r: 800, type: 'num', q: `В треугольнике два угла равны 47° и 68°. Найдите третий угол (в градусах).`, a: ['65'],
        hints: [`Сумма углов треугольника равна 180°.`],
        sol: `180° − 47° − 68° = 65°.` },
      { id: 'tri-02', lvl: 1, r: 830, type: 'num', q: `Внешний угол треугольника ABC при вершине C равен 130°, а угол A равен 55°. Найдите угол B (в градусах).`, a: ['75'],
        hints: [`Внешний угол равен сумме двух внутренних углов, не смежных с ним.`],
        sol: `130° = ∠A + ∠B, поэтому ∠B = 130° − 55° = 75°.` },
      { id: 'tri-03', lvl: 1, r: 860, type: 'choice', q: `Из каких трёх отрезков можно составить треугольник?`, opts: ['2, 3, 6', '3, 4, 8', '5, 6, 10', '1, 2, 3'], a: 2,
        hints: [`Каждая сторона должна быть меньше суммы двух других. Достаточно проверить самую большую.`],
        sol: `Проверяем наибольший отрезок: 6 > 2 + 3, 8 > 3 + 4, 10 < 5 + 6, 3 = 1 + 2. Подходит только 5, 6, 10. Из отрезков 1, 2, 3 «треугольник» вырождается в отрезок.` },
      { id: 'tri-04', lvl: 1, r: 890, type: 'num', q: `В равнобедренном треугольнике угол между боковыми сторонами равен 40°. Найдите угол при основании (в градусах).`, a: ['70'],
        hints: [`Углы при основании равны.`],
        sol: `(180° − 40°) : 2 = 70°.` },
      { id: 'tri-05', lvl: 1, r: 920, type: 'num', q: `Две стороны треугольника равны 3 и 8, а третья сторона — целое число. Сколько существует возможных значений третьей стороны?`, a: ['5'],
        hints: [`Третья сторона больше разности двух других и меньше их суммы.`],
        sol: `8 − 3 < c < 8 + 3, то есть 5 < c < 11: c = 6, 7, 8, 9, 10. Ответ: 5.` },
      { id: 'tri-06', lvl: 1, r: 960, type: 'num', q: `Катеты прямоугольного треугольника равны 5 и 12. Найдите гипотенузу.`, a: ['13'],
        hints: [`Теорема Пифагора: c<sup>2</sup> = a<sup>2</sup> + b<sup>2</sup>.`],
        sol: `c<sup>2</sup> = 25 + 144 = 169, c = 13.` },
      { id: 'tri-07', lvl: 1, r: 1000, type: 'num', q: `Стороны треугольника равны 6, 8 и 10. Найдите длину средней линии, параллельной наибольшей стороне.`, a: ['5'],
        hints: [`Средняя линия равна половине стороны, которой она параллельна.`],
        sol: `10 : 2 = 5.` },
      { id: 'tri-08', lvl: 1, r: 1040, type: 'choice', q: `В треугольнике ABC стороны AB = 7, BC = 5, AC = 9. Какой угол треугольника наибольший?`, opts: ['∠A', '∠B', '∠C', 'все углы равны'], a: 1,
        hints: [`Против большей стороны лежит больший угол.`],
        sol: `Наибольшая сторона — AC = 9, против неё лежит угол B.` },

      // Уровень 2
      { id: 'tri-09', lvl: 2, r: 1070, type: 'num', q: `В прямоугольном треугольнике медиана, проведённая к гипотенузе, равна 6,5, а один из катетов равен 5. Найдите другой катет.`, a: ['12'],
        hints: [`Медиана, проведённая к гипотенузе, равна половине гипотенузы.`, `Гипотенуза равна 13.`],
        sol: `Гипотенуза равна 2 · 6,5 = 13, второй катет ${sq('13<sup>2</sup> − 5<sup>2</sup>')} = ${sq('144')} = 12.` },
      { id: 'tri-10', lvl: 2, r: 1100, type: 'num', q: `Медианы треугольника ABC пересекаются в точке M. Медиана ${s1.replace('A', 'AA')} равна 15. Найдите AM.`, a: ['10'],
        hints: [`Точка пересечения медиан делит каждую медиану в отношении 2 : 1, считая от вершины.`],
        sol: `AM = ${fr('2', '3')} · 15 = 10.` },
      { id: 'tri-11', lvl: 2, r: 1130, type: 'num', q: `В треугольнике ABC стороны AB = 6, AC = 9, BC = 10. Биссектриса угла A пересекает BC в точке D. Найдите BD.${fig11}`, a: ['4'],
        hints: [`Биссектриса делит противоположную сторону в отношении прилежащих сторон: BD : DC = AB : AC.`],
        sol: `BD : DC = 6 : 9 = 2 : 3, а BD + DC = 10. Значит, BD = 10 · ${fr('2', '5')} = 4.` },
      { id: 'tri-12', lvl: 2, r: 1160, type: 'num', q: `Прямая, параллельная стороне AC треугольника ABC, пересекает стороны AB и BC в точках M и N, причём BM : MA = 2 : 3. Площадь треугольника ABC равна 50. Найдите площадь треугольника MBN.${fig12}`, a: ['8'],
        hints: [`Треугольник MBN подобен треугольнику ABC. Найди коэффициент подобия.`, `BM : BA = 2 : 5. Площади подобных треугольников относятся как квадрат коэффициента.`],
        sol: `Треугольники MBN и ABC подобны с коэффициентом BM : BA = 2 : 5. Площади относятся как (${fr('2', '5')})<sup>2</sup> = ${fr('4', '25')}, поэтому площадь MBN равна 50 · ${fr('4', '25')} = 8.` },
      { id: 'tri-13', lvl: 2, r: 1190, type: 'num', q: `В треугольнике ABC угол B равен 72°. Биссектрисы углов A и C пересекаются в точке I. Найдите угол AIC (в градусах).`, a: ['126'],
        hints: [`∠A + ∠C = 180° − 72° = 108°.`, `В треугольнике AIC углы при A и C — половины углов A и C треугольника.`],
        sol: `∠IAC + ∠ICA = ${fr('1', '2')}(∠A + ∠C) = ${fr('1', '2')} · 108° = 54°, поэтому ∠AIC = 180° − 54° = 126°. Общая формула: ∠AIC = 90° + ${fr('1', '2')}∠B.` },
      { id: 'tri-14', lvl: 2, r: 1220, type: 'num', q: `В прямоугольном треугольнике высота, проведённая к гипотенузе, делит её на отрезки 4 и 9. Найдите эту высоту.`, a: ['6'],
        hints: [`Квадрат высоты к гипотенузе равен произведению отрезков гипотенузы: h<sup>2</sup> = pq.`],
        sol: `h<sup>2</sup> = 4 · 9 = 36, h = 6.` },
      { id: 'tri-15', lvl: 2, r: 1250, type: 'num', q: `Катеты прямоугольного треугольника равны 9 и 12. Найдите высоту, проведённую к гипотенузе. Ответ запишите десятичной дробью.`, a: ['7.2', '36/5'],
        hints: [`Площадь можно посчитать двумя способами: через катеты и через гипотенузу и высоту.`, `Гипотенуза равна 15.`],
        sol: `Гипотенуза ${sq('81 + 144')} = 15. Площадь ${fr('9 · 12', '2')} = 54 = ${fr('15 · h', '2')}, откуда h = ${fr('108', '15')} = 7,2.` },
      { id: 'tri-16', lvl: 2, r: 1280, type: 'num', q: `Найдите радиус окружности, вписанной в прямоугольный треугольник с катетами 8 и 15.`, a: ['3'],
        hints: [`Для прямоугольного треугольника r = ${fr('a + b − c', '2')}, где c — гипотенуза.`, `Гипотенуза равна 17.`],
        sol: `c = ${sq('64 + 225')} = 17, r = ${fr('8 + 15 − 17', '2')} = 3.` },
      { id: 'tri-17', lvl: 2, r: 1310, type: 'num', q: `В треугольнике ABC стороны AB и BC равны. На стороне BC отмечена точка D так, что AD = AC. Известно, что ∠BAD = 21°. Найдите угол ABC (в градусах).${fig17}`, a: ['46'],
        hints: [`Обозначь ∠BAC = ∠BCA = α.`, `Треугольник ADC равнобедренный: ∠ADC = ∠ACD = α. Вырази ∠DAC.`, `∠BAD = α − ∠DAC = 3α − 180°.`],
        sol: `Пусть ∠BAC = ∠BCA = α. В равнобедренном треугольнике ADC ∠ADC = ∠ACD = α, поэтому ∠DAC = 180° − 2α. Тогда ∠BAD = α − (180° − 2α) = 3α − 180° = 21°, откуда α = 67° и ∠ABC = 180° − 2 · 67° = 46°.` },
      { id: 'tri-18', lvl: 2, r: 1340, type: 'num', q: `Периметр треугольника равен 30, длины его сторон — целые числа, одна из сторон равна 12. Сколько существует таких треугольников? Треугольники, которые отличаются только порядком сторон, считаются одинаковыми.`, a: ['6'],
        hints: [`Две другие стороны b ≤ c в сумме дают 18.`, `Неравенство треугольника: c < b + 12.`],
        sol: `b + c = 18, b ≤ c. Неравенство треугольника c < b + 12 даёт 18 − 2b < 12, то есть b > 3, а b ≤ 9; условие b + c > 12 выполнено. Значит, b = 4, 5, 6, 7, 8, 9 — шесть треугольников.` },

      // Уровень 3
      { id: 'tri-19', lvl: 3, r: 1370, type: 'num', q: `Катеты прямоугольного треугольника равны 6 и 8. Найдите расстояние от точки пересечения медиан до вершины прямого угла. Ответ запишите несократимой дробью.`, a: ['10/3'],
        hints: [`Медиана из вершины прямого угла равна половине гипотенузы.`, `Точка пересечения медиан делит медиану в отношении 2 : 1, считая от вершины.`],
        sol: `Гипотенуза 10, медиана к ней 5. Искомое расстояние ${fr('2', '3')} · 5 = ${fr('10', '3')}.` },
      { id: 'tri-20', lvl: 3, r: 1400, type: 'num', q: `Биссектриса BD треугольника ABC делит сторону AC на отрезки AD = 4 и DC = 6. Периметр треугольника равен 30. Найдите AB.`, a: ['8'],
        hints: [`AB : BC = AD : DC = 2 : 3.`, `AB + BC = 30 − 10 = 20.`],
        sol: `По свойству биссектрисы AB : BC = 4 : 6 = 2 : 3. AB + BC = 30 − 10 = 20, поэтому AB = 20 · ${fr('2', '5')} = 8.` },
      { id: 'tri-21', lvl: 3, r: 1430, type: 'num', q: `В треугольнике ABC угол C прямой, CH — высота, AH = 4, AC = 6. Найдите AB.${fig21}`, a: ['9'],
        hints: [`Треугольники ACH и ABC подобны: у них общий угол A.`, `AC<sup>2</sup> = AH · AB.`],
        sol: `Треугольники ACH и ABC подобны по двум углам, поэтому ${fr('AC', 'AB')} = ${fr('AH', 'AC')}, то есть AC<sup>2</sup> = AH · AB: 36 = 4 · AB, AB = 9.` },
      { id: 'tri-22', lvl: 3, r: 1460, type: 'num', q: `Углы треугольника относятся как 1 : 2 : 3. Наибольшая сторона равна 12. Найдите наименьшую сторону.`, a: ['6'],
        hints: [`Найди углы: x + 2x + 3x = 180°.`, `Катет против угла 30° равен половине гипотенузы.`],
        sol: `Углы равны 30°, 60° и 90°. Наибольшая сторона — гипотенуза 12, наименьшая лежит против угла 30° и равна 6.` },
      { id: 'tri-23', lvl: 3, r: 1490, type: 'num', q: `В треугольнике ABC ∠A = 40°, ∠B = 60°, CH — высота, CL — биссектриса. Найдите угол HCL (в градусах).`, a: ['10'],
        hints: [`∠C = 80°, биссектриса делит его пополам.`, `В прямоугольном треугольнике ACH найди ∠ACH.`],
        sol: `∠C = 80°, поэтому ∠ACL = 40°. В прямоугольном треугольнике ACH ∠ACH = 90° − 40° = 50°. Значит, ∠HCL = 50° − 40° = 10°.` },
      { id: 'tri-24', lvl: 3, r: 1520, type: 'num', q: `Медианы ${s1.replace('A', 'AA')} и ${b1.replace('B', 'BB')} треугольника ABC пересекаются в точке M. Площадь треугольника ABC равна 60. Найдите площадь четырёхугольника ${s1}M${b1}C.${fig24}`, a: ['20'],
        hints: [`Три медианы делят треугольник на шесть треугольников равной площади.`, `Четырёхугольник состоит из двух таких треугольников.`],
        sol: `Три медианы делят треугольник на шесть треугольников площадью 60 : 6 = 10. Четырёхугольник ${s1}M${b1}C состоит из треугольников CM${s1} и CM${b1} (отрезок CM лежит на третьей медиане), поэтому его площадь равна 20.` },
      { id: 'tri-25', lvl: 3, r: 1550, type: 'num', q: `На стороне AC треугольника ABC отмечена точка D так, что ∠ABD = ∠ACB. Известно, что AB = 6, AC = 9. Найдите AD.${fig25}`, a: ['4'],
        hints: [`Найди два подобных треугольника с общим углом A.`, `Треугольники ABD и ACB подобны.`],
        sol: `У треугольников ABD и ACB общий угол A и ∠ABD = ∠ACB, значит, они подобны: ${fr('AD', 'AB')} = ${fr('AB', 'AC')}. Отсюда AD = ${fr('AB<sup>2</sup>', 'AC')} = ${fr('36', '9')} = 4.` },
      { id: 'tri-26', lvl: 3, r: 1580, type: 'choice', q: `В треугольнике ABC стороны BC = 6 и AC = 8, а медианы, проведённые из вершин A и B, перпендикулярны. Найдите AB.`, opts: [`2${sq('5')}`, '5', sq('50'), '10'], a: 0,
        hints: [`Пусть медианы ${s1.replace('A', 'AA')} и ${b1.replace('B', 'BB')} пересекаются в M. Обозначь M${s1} = x, M${b1} = y; тогда AM = 2x, BM = 2y.`, `Запиши теорему Пифагора для треугольников BM${s1}, AM${b1} и AMB.`],
        sol: `Пусть M${s1} = x, M${b1} = y, тогда AM = 2x, BM = 2y. Из прямоугольных треугольников BM${s1} и AM${b1}: 4y<sup>2</sup> + x<sup>2</sup> = 3<sup>2</sup> = 9 и 4x<sup>2</sup> + y<sup>2</sup> = 4<sup>2</sup> = 16. Сложив, получаем 5(x<sup>2</sup> + y<sup>2</sup>) = 25, то есть x<sup>2</sup> + y<sup>2</sup> = 5. Тогда AB<sup>2</sup> = 4x<sup>2</sup> + 4y<sup>2</sup> = 20 и AB = 2${sq('5')}.` },
      { id: 'tri-27', lvl: 3, r: 1610, type: 'num', q: `В прямоугольном треугольнике биссектриса прямого угла делит гипотенузу на отрезки 15 и 20. Найдите площадь треугольника.`, a: ['294'],
        hints: [`Катеты относятся как отрезки гипотенузы: 15 : 20 = 3 : 4.`, `Пусть катеты 3t и 4t; тогда гипотенуза 5t = 35.`],
        sol: `По свойству биссектрисы катеты относятся как 3 : 4; пусть они равны 3t и 4t. Гипотенуза 5t = 35, t = 7, катеты 21 и 28. Площадь ${fr('21 · 28', '2')} = 294.` },
      { id: 'tri-28', lvl: 3, r: 1640, type: 'num', q: `Через точку пересечения медиан треугольника ABC проведена прямая, параллельная стороне AC. Она пересекает стороны AB и BC в точках M и N. AC = 18. Найдите MN.`, a: ['12'],
        hints: [`Пусть ${b1.replace('B', 'BB')} — медиана. Прямая MN отсекает треугольник MBN, подобный треугольнику ABC.`, `Точка пересечения медиан делит ${b1.replace('B', 'BB')} в отношении 2 : 1 от B — это и есть коэффициент подобия.`],
        sol: `Треугольник MBN подобен ABC. Медиана ${b1.replace('B', 'BB')} пересекает MN в точке пересечения медиан G, и BG : B${b1} = 2 : 3 — это коэффициент подобия. Значит, MN = ${fr('2', '3')} · 18 = 12.` },

      // Уровень 4
      { id: 'tri-29', lvl: 4, r: 1680, type: 'proof', q: `Докажите, что в прямоугольном треугольнике медиана, проведённая к гипотенузе, равна половине гипотенузы.`,
        hints: [`Пусть ∠C = 90°, M — середина AB. Отложи на продолжении CM отрезок MD = CM.`, `Диагонали прямоугольника равны и делятся точкой пересечения пополам.`],
        sol: `Пусть ∠C = 90°, M — середина AB. Отложим на продолжении CM отрезок MD = CM. Диагонали четырёхугольника ACBD делятся точкой M пополам, значит, это параллелограмм, а с прямым углом C — прямоугольник. Диагонали прямоугольника равны: CD = AB. Поэтому CM = ${fr('1', '2')}CD = ${fr('1', '2')}AB.`,
        rubric: [[2, `Удвоение медианы`], [3, `Обосновано, что ACBD — прямоугольник`], [2, `Вывод из равенства диагоналей`]] },
      { id: 'tri-30', lvl: 4, r: 1720, type: 'proof', q: `Докажите, что в равнобедренном треугольнике медианы, проведённые к боковым сторонам, равны.`,
        hints: [`Пусть AB = AC, M и N — середины AB и AC. Сравни треугольники MBC и NCB.`],
        sol: `Пусть AB = AC, M — середина AB, N — середина AC. Тогда BM = ${fr('1', '2')}AB = ${fr('1', '2')}AC = CN. В треугольниках MBC и NCB сторона BC общая, BM = CN, ∠MBC = ∠NCB как углы при основании. По первому признаку треугольники равны, значит, CM = BN.`,
        rubric: [[2, `Выбраны треугольники MBC и NCB`], [3, `Проверены три условия признака равенства`], [2, `Вывод`]] },
      { id: 'tri-31', lvl: 4, r: 1760, type: 'proof', q: `Докажите, что медиана AM треугольника ABC меньше полусуммы сторон AB и AC.`,
        hints: [`Удвой медиану: отложи на продолжении AM отрезок MD = AM.`, `ABDC — параллелограмм, BD = AC.`, `Неравенство треугольника для ABD.`],
        sol: `Отложим на продолжении AM отрезок MD = AM. Диагонали четырёхугольника ABDC делятся точкой M пополам, поэтому это параллелограмм и BD = AC. Точки A, B, D не лежат на одной прямой, и в треугольнике ABD: AD < AB + BD, то есть 2AM < AB + AC.`,
        rubric: [[3, `Удвоение медианы и параллелограмм`], [3, `Неравенство треугольника для ABD`], [1, `Вывод`]] },
      { id: 'tri-32', lvl: 4, r: 1800, type: 'proof', q: `Докажите, что биссектриса AD треугольника ABC делит сторону BC в отношении BD : DC = AB : AC.`,
        hints: [`Проведи через C прямую, параллельную AD, до пересечения с продолжением BA в точке E.`, `Докажи, что треугольник ACE равнобедренный.`, `Примени теорему о пропорциональных отрезках.`],
        sol: `Проведём через C прямую, параллельную AD; пусть она пересекает продолжение BA за точку A в точке E. Тогда ∠AEC = ∠BAD как соответственные, ∠ACE = ∠DAC как накрест лежащие, а ∠BAD = ∠DAC. Значит, ∠AEC = ∠ACE, и треугольник ACE равнобедренный: AE = AC. Так как AD ∥ EC, по теореме о пропорциональных отрезках BD : DC = BA : AE = AB : AC.`,
        rubric: [[2, `Построение: прямая через C, параллельная AD`], [2, `Доказано AE = AC`], [2, `Применены пропорциональные отрезки или подобие`], [1, `Вывод`]] },
      { id: 'tri-33', lvl: 4, r: 1840, type: 'proof', q: `Докажите, что медианы треугольника пересекаются в одной точке и делятся ею в отношении 2 : 1, считая от вершины.`,
        hints: [`Пусть медианы ${s1.replace('A', 'AA')} и ${b1.replace('B', 'BB')} пересекаются в точке G. ${s1}${b1} — средняя линия.`, `Треугольники GAB и G${s1}${b1} подобны с коэффициентом 2.`, `Значит, любая медиана пересекает ${s1.replace('A', 'AA')} в точке, которая делит её в отношении 2 : 1 от A.`],
        sol: `Пусть медианы ${s1.replace('A', 'AA')} и ${b1.replace('B', 'BB')} пересекаются в точке G. ${s1}${b1} — средняя линия: ${s1}${b1} ∥ AB и ${s1}${b1} = ${fr('1', '2')}AB. Треугольники GAB и G${s1}${b1} подобны по двум углам (накрест лежащие углы при параллельных) с коэффициентом 2, поэтому AG = 2G${s1} и BG = 2G${b1}. Значит, медиана ${b1.replace('B', 'BB')} делит ${s1.replace('A', 'AA')} в отношении 2 : 1 от вершины A. По тому же рассуждению медиана CC<sub>1</sub> тоже делит ${s1.replace('A', 'AA')} в отношении 2 : 1 от A, то есть проходит через ту же точку G.`,
        rubric: [[2, `Средняя линия ${s1}${b1}`], [2, `Подобие треугольников GAB и G${s1}${b1}, отношение 2 : 1`], [3, `Обосновано, что третья медиана проходит через ту же точку`]] },
      { id: 'tri-34', lvl: 4, r: 1880, type: 'proof', q: `В прямоугольном треугольнике ABC (∠C = 90°) проведена высота CH. Докажите, что CH<sup>2</sup> = AH · HB.`,
        hints: [`Найди подобные треугольники среди ACH, CBH и ABC.`, `∠ACH = ∠B: оба угла дополняют ∠A до 90°.`],
        sol: `В прямоугольном треугольнике ACH ∠ACH = 90° − ∠A = ∠B. Прямоугольные треугольники ACH и CBH подобны по острому углу: ∠ACH = ∠CBH. Значит, ${fr('CH', 'HB')} = ${fr('AH', 'CH')}, то есть CH<sup>2</sup> = AH · HB.`,
        rubric: [[3, `Доказано ∠ACH = ∠B`], [2, `Подобие треугольников ACH и CBH`], [2, `Пропорция и вывод`]] },
      { id: 'tri-35', lvl: 4, r: 1920, type: 'proof', q: `Докажите, что сумма медиан треугольника меньше его периметра, но больше ${fr('3', '4')} периметра.`,
        hints: [`Сверху: m<sub>a</sub> < ${fr('b + c', '2')} (удвоение медианы). Сложи для трёх медиан.`, `Снизу: пусть G — точка пересечения медиан. Неравенство треугольника для AGB: AG + BG > AB.`, `AG = ${fr('2', '3')}m<sub>a</sub>.`],
        sol: `Сверху: удвоением медианы получаем m<sub>a</sub> < ${fr('b + c', '2')}, и так же для m<sub>b</sub>, m<sub>c</sub>. Сложив, получаем m<sub>a</sub> + m<sub>b</sub> + m<sub>c</sub> < a + b + c. Снизу: пусть G — точка пересечения медиан. Из треугольника AGB: ${fr('2', '3')}m<sub>a</sub> + ${fr('2', '3')}m<sub>b</sub> > c, и так же для двух других пар. Сложив, получаем ${fr('4', '3')}(m<sub>a</sub> + m<sub>b</sub> + m<sub>c</sub>) > a + b + c, то есть сумма медиан больше ${fr('3', '4')} периметра.`,
        rubric: [[3, `Верхняя оценка через m<sub>a</sub> < (b + c)/2`], [3, `Нижняя оценка через треугольники AGB, BGC, CGA`], [1, `Вывод`]] },
      { id: 'tri-36', lvl: 4, r: 1950, type: 'num', q: `Медиана BM треугольника ABC вдвое меньше стороны AB и образует с ней угол 40°. Найдите угол ABC (в градусах).${fig36}`, a: ['110'],
        hints: [`Удвой медиану: отложи на продолжении BM отрезок MD = BM.`, `ABCD — параллелограмм, BD = 2BM = AB, и треугольник ABD равнобедренный.`, `∠DBC = ∠ADB как накрест лежащие при AD ∥ BC.`],
        sol: `Отложим на продолжении BM отрезок MD = BM. Диагонали четырёхугольника ABCD делятся точкой M пополам, поэтому ABCD — параллелограмм. BD = 2BM = AB, так что треугольник ABD равнобедренный с углом 40° при вершине B, и ∠ADB = (180° − 40°) : 2 = 70°. Так как AD ∥ BC, ∠DBC = ∠ADB = 70°. Значит, ∠ABC = 40° + 70° = 110°.` },

      // Уровень 5
      { id: 'tri-37', lvl: 5, r: 2060, type: 'proof', q: `В остроугольном треугольнике ABC проведены высоты ${s1.replace('A', 'AA')} и ${b1.replace('B', 'BB')}. Докажите, что треугольник ${s1}${b1}C подобен треугольнику ABC, и найдите коэффициент подобия.`,
        hints: [`Сравни прямоугольные треугольники ${s1.replace('A', 'AA')}C и ${b1.replace('B', 'BB')}C: у них общий острый угол C.`, `Получится C${s1} : C${b1} = CA : CB.`, `Второй признак подобия для ${s1}${b1}C и ABC. Какая вершина какой соответствует?`],
        sol: `Прямоугольные треугольники ${s1.replace('A', 'AA')}C и ${b1.replace('B', 'BB')}C подобны (общий острый угол C), поэтому C${s1} : C${b1} = CA : CB, то есть ${fr('C' + s1, 'CA')} = ${fr('C' + b1, 'CB')}. Вместе с общим углом C это даёт подобие треугольников ${s1}${b1}C и ABC по второму признаку, причём ${s1} соответствует A, а ${b1} — B. Коэффициент подобия равен ${fr('C' + s1, 'CA')} = cos C. В частности, ∠C${s1}${b1} = ∠CAB.`,
        rubric: [[3, `Подобие треугольников ${s1.replace('A', 'AA')}C и ${b1.replace('B', 'BB')}C и пропорция`], [3, `Второй признак подобия с верным соответствием вершин`], [1, `Коэффициент cos C`]] },
      { id: 'tri-38', lvl: 5, r: 2150, type: 'proof', q: `В треугольнике ABC угол B вдвое больше угла C. Докажите, что AC<sup>2</sup> = AB<sup>2</sup> + AB · BC.`,
        hints: [`Проведи биссектрису BD угла B. Тогда ∠ABD = ∠DBC = ∠C.`, `Треугольники ABD и ACB подобны: общий угол A и ∠ABD = ∠ACB.`, `Из подобия AB<sup>2</sup> = AD · AC. Вырази AD ещё и по свойству биссектрисы.`],
        sol: `Пусть BD — биссектриса угла B; тогда ∠ABD = ∠DBC = ∠C. Треугольники ABD и ACB подобны (общий угол A, ∠ABD = ∠ACB), поэтому ${fr('AD', 'AB')} = ${fr('AB', 'AC')} и AD = ${fr('AB<sup>2</sup>', 'AC')}. По свойству биссектрисы ${fr('AD', 'DC')} = ${fr('AB', 'BC')}, откуда AD = ${fr('AC · AB', 'AB + BC')}. Приравнивая, получаем ${fr('AB<sup>2</sup>', 'AC')} = ${fr('AC · AB', 'AB + BC')}, то есть AB(AB + BC) = AC<sup>2</sup>.`,
        rubric: [[2, `Биссектриса угла B и равные углы`], [2, `Подобие ABD и ACB, AD = AB<sup>2</sup>/AC`], [2, `Свойство биссектрисы: AD = AC · AB/(AB + BC)`], [1, `Вывод`]] },
      { id: 'tri-39', lvl: 5, r: 2240, type: 'proof', q: `В треугольнике ABC стороны AB и AC равны, ∠A = 20°. На стороне AC отмечена точка D так, что AD = BC. Докажите, что ∠ABD = 10°.`,
        hints: [`Углы при основании равны 80°. Построй внутри треугольника равносторонний треугольник BCE.`, `Точка E равноудалена от B и C, поэтому лежит на оси симметрии треугольника ABC. Чему равны ∠BAE и ∠ABE?`, `Сравни треугольники ABE и BAD.`],
        sol: `Углы B и C равны 80°. Построим равносторонний треугольник BCE, точка E — по ту же сторону от BC, что и A; так как BC < AB, точка E лежит внутри треугольника ABC. Точка E равноудалена от B и C, поэтому лежит на оси симметрии треугольника ABC, и ∠BAE = 10°. Кроме того, ∠ABE = 80° − 60° = 20°. Треугольники ABE и BAD равны по двум сторонам и углу между ними: AB — общая, BE = BC = AD, ∠ABE = ∠BAD = 20°. При этом вершина A первого соответствует вершине B второго, поэтому ∠ABD = ∠BAE = 10°.`,
        rubric: [[2, `Построен равносторонний треугольник BCE`], [2, `Найдены ∠BAE = 10° и ∠ABE = 20°`], [2, `Равенство треугольников ABE и BAD`], [1, `Вывод с верным соответствием вершин`]] },
      { id: 'tri-40', lvl: 5, r: 2350, type: 'proof', q: `В треугольнике ABC биссектрисы BD и CE равны. Докажите, что AB = AC (теорема Штейнера — Лемуса).`,
        hints: [`Предположи, что ∠B > ∠C. Сравни треугольники BEC и CDB: у них общая сторона BC и BD = CE. Где угол между равными сторонами больше?`, `Если у двух треугольников две стороны равны, то против большего угла между ними лежит большая третья сторона. Отсюда CD > BE.`, `Построй параллелограмм BDFE. Треугольник CEF равнобедренный (EF = BD = CE). Сравни углы ∠ECF и ∠EFC.`],
        sol: `Предположим, что ∠B > ∠C. В треугольниках BEC и CDB сторона BC общая и CE = BD, а углы между ними ∠ECB = ${fr('1', '2')}∠C < ${fr('1', '2')}∠B = ∠DBC. Значит, третья сторона против меньшего угла меньше: BE < CD. Построим параллелограмм BDFE. Тогда EF = BD = CE, DF = BE, ∠EFD = ∠EBD = ${fr('1', '2')}∠B. Треугольник CEF равнобедренный, поэтому ∠EFC = ∠ECF, то есть ${fr('1', '2')}∠B + ∠DFC = ${fr('1', '2')}∠C + ∠DCF. В треугольнике CDF сторона DF = BE меньше CD, поэтому ∠DCF < ∠DFC. Но тогда левая часть равенства больше правой — противоречие. Так же невозможно ∠B < ∠C. Значит, ∠B = ∠C и AB = AC.`,
        rubric: [[2, `Предположение ∠B > ∠C и вывод CD > BE`], [2, `Параллелограмм BDFE и равнобедренный треугольник CEF`], [2, `Сравнение углов и противоречие`], [1, `Симметричный случай и вывод`]] }
    ]
  });
})();

// ---- content/tri-deep.js ----
// Глубокий уровень темы «Треугольники»: приёмы международных олимпиад.
// Прямая Эйлера и окружность девяти точек, лемма о трезубце, изогональное сопряжение.
// Координаты точек на чертежах вычисляются здесь же, поэтому чертежи точные.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function sq(x) { return '<span class="sq">√<span>' + x + '</span></span>'; }
  const s = (L, i) => L + '<sub>' + i + '</sub>';
  const A1 = s('A', 1), B1 = s('B', 1), C1 = s('C', 1), A2 = s('A', 2), B2 = s('B', 2), C2 = s('C', 2), Ia = s('I', 'a');
  const Pa = s('P', 'a'), Pb = s('P', 'b'), Pc = s('P', 'c'), Qa = s('Q', 'a'), Qb = s('Q', 'b'), Qc = s('Q', 'c');

  // геометрия для чертежей
  const F = MM.fig;
  const sub = (p, q) => [p[0] - q[0], p[1] - q[1]], add = (p, q) => [p[0] + q[0], p[1] + q[1]], mul = (p, k) => [p[0] * k, p[1] * k];
  const mid = (p, q) => [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2], dist = (p, q) => Math.hypot(p[0] - q[0], p[1] - q[1]);
  function circum(A, B, C) {
    const d = 2 * (A[0] * (B[1] - C[1]) + B[0] * (C[1] - A[1]) + C[0] * (A[1] - B[1]));
    const a = A[0] * A[0] + A[1] * A[1], b = B[0] * B[0] + B[1] * B[1], c = C[0] * C[0] + C[1] * C[1];
    return [(a * (B[1] - C[1]) + b * (C[1] - A[1]) + c * (A[1] - B[1])) / d, (a * (C[0] - B[0]) + b * (A[0] - C[0]) + c * (B[0] - A[0])) / d];
  }
  const orth = (A, B, C) => { const O = circum(A, B, C); return [A[0] + B[0] + C[0] - 2 * O[0], A[1] + B[1] + C[1] - 2 * O[1]]; };
  const foot = (P, A, B) => { const d = sub(B, A), t = ((P[0] - A[0]) * d[0] + (P[1] - A[1]) * d[1]) / (d[0] * d[0] + d[1] * d[1]); return add(A, mul(d, t)); };
  const wsum = (w, p) => { const t = w[0] + w[1] + w[2]; return [(w[0] * p[0][0] + w[1] * p[1][0] + w[2] * p[2][0]) / t, (w[0] * p[0][1] + w[1] * p[1][1] + w[2] * p[2][1]) / t]; };
  const incenter = (A, B, C) => wsum([dist(B, C), dist(C, A), dist(A, B)], [A, B, C]);
  const excenterA = (A, B, C) => wsum([-dist(B, C), dist(C, A), dist(A, B)], [A, B, C]);
  // вторая точка пересечения прямой PQ с окружностью с центром O, если P лежит на окружности
  const second = (P, Q, O) => { const u = sub(Q, P), l = Math.hypot(u[0], u[1]), e = [u[0] / l, u[1] / l], t = 2 * ((O[0] - P[0]) * e[0] + (O[1] - P[1]) * e[1]); return add(P, mul(e, t)); };

  const figE = (() => {
    const A = [1, 4], B = [0, 0], C = [7, 0], O = circum(A, B, C), H = orth(A, B, C), G = [8 / 3, 4 / 3];
    const E1 = add(H, mul(sub(H, O), 0.45)), E2 = add(O, mul(sub(O, H), 0.45));
    return F({ pts: { A, B, C, D: foot(A, B, C), A1: mid(B, C), H, G, O, E1, E2 }, hide: ['E1', 'E2'], poly: ['ABC'],
      seg: [['A', 'H'], ['O', 'A1']], dash: [['H', 'D'], ['A', 'A1']], gold: [['E1', 'E2']], right: [['A', 'D', 'C'], ['O', 'A1', 'C']],
      lab: { D: 's', A1: 's', H: 'w', G: 's', O: 'ne' }, w: 320, alt: 'Прямая Эйлера: ортоцентр H, точка пересечения медиан G и центр описанной окружности O лежат на одной прямой' });
  })();
  const figN = (() => {
    const A = [1.5, 5], B = [0, 0], C = [7, 0], O = circum(A, B, C), H = orth(A, B, C), N = mid(O, H), R = dist(O, A);
    const p = { A, B, C, H, N, A1: mid(B, C), B1: mid(C, A), C1: mid(A, B), A2: mid(A, H), B2: mid(B, H), C2: mid(C, H), D: foot(A, B, C), E: foot(B, C, A), K: foot(C, A, B) };
    return F({ pts: p, poly: ['ABC'], circ: [{ c: 'N', r: R / 2 }], dash: [['A', 'D'], ['B', 'E'], ['C', 'K']], gold: [['A1', 'A2']], right: [['A', 'D', 'C']],
      nolab: ['B1', 'C1', 'B2', 'C2', 'E', 'K'], lab: { D: 's', A1: 's', A2: 'ne', H: 'w', N: 'e' }, w: 320,
      alt: 'Окружность девяти точек: середины сторон, основания высот и середины отрезков от вершин до ортоцентра H' });
  })();
  const figT = (() => {
    const A = [1.6, 4.4], B = [0, 0], C = [5, 0], O = circum(A, B, C), I = incenter(A, B, C), W = second(A, I, O);
    return F({ pts: { A, B, C, I, W, I_a: excenterA(A, B, C) }, poly: ['ABC'], circ: [{ c: O, r: dist(O, A) }, { c: 'W', r: dist(W, B), dash: true }],
      seg: [['A', 'I']], gold: [['W', 'B'], ['W', 'C'], ['I', 'I_a']], ticks: { WB: 1, WC: 1, WI: 1, 'W-I_a': 1 }, lab: { W: 'e', I: 'e', I_a: 'e' }, w: 300,
      alt: 'Лемма о трезубце: точки B, C, I и центр вневписанной окружности лежат на окружности с центром W' });
  })();
  const figIso = (() => {
    const A = [2, 3.4], B = [0, 0], C = [6, 0];
    const tB = Math.atan2(B[1] - A[1], B[0] - A[0]), tC = Math.atan2(C[1] - A[1], C[0] - A[0]), phi = (tC - tB) * 0.3;
    const onBC = t => [A[0] - A[1] * Math.cos(t) / Math.sin(t), 0];
    return F({ pts: { A, B, C, X: onBC(tB + phi), Y: onBC(tC - phi), L: onBC((tB + tC) / 2) }, poly: ['ABC'], seg: [['A', 'X'], ['A', 'Y']], dash: [['A', 'L']],
      ang: [['B', 'A', 'X', 1, 34], ['Y', 'A', 'C', 1, 34]], lab: { X: 's', Y: 's', L: 's' }, w: 300, alt: 'Изогональные прямые AX и AY симметричны относительно биссектрисы AL' });
  })();
  const fig46 = (() => {
    const A = [4.2, 2.6], B = [0, 0], C = [5, 0], O = circum(A, B, C), I = incenter(A, B, C), W = second(A, I, O);
    return F({ pts: { A, B, C, I, P: add(A, mul(sub(B, A), dist(A, C) / dist(A, B))) }, poly: ['ABC'], circ: [{ c: W, r: dist(W, B) }],
      lab: { P: 'nw', I: 'n' }, w: 250, alt: 'Окружность через точки B, I, C второй раз пересекает прямую AB в точке P' });
  })();

  MM.addDeep('tri', {
    lessons: [
      { id: 'tri-l7', title: 'Прямая Эйлера и окружность девяти точек', mins: 16, html: `
<p>Три из четырёх замечательных точек — центр описанной окружности <span class="m">O</span>, точка пересечения медиан <span class="m">G</span> и ортоцентр <span class="m">H</span> — всегда лежат на одной прямой. Это доказал Леонард Эйлер в 1765 году. На олимпиадах эти факты можно применять как известные, но идеи их доказательств решают задачи сами по себе.</p>
<p>Обозначения: <span class="m">R</span> — радиус описанной окружности, <span class="m">${A1}</span>, <span class="m">${B1}</span>, <span class="m">${C1}</span> — середины сторон <span class="m">BC</span>, <span class="m">CA</span>, <span class="m">AB</span>.</p>
<h3>Главная лемма</h3>
<div class="box"><div class="box-h">Лемма</div>
<p><span class="m">AH = 2 · O${A1}</span>, и отрезки <span class="m">AH</span> и <span class="m">O${A1}</span> параллельны.</p></div>
<p><b>Доказательство.</b> Стороны треугольника <span class="m">${A1}${B1}${C1}</span> — средние линии треугольника <span class="m">ABC</span>: они параллельны его сторонам и вдвое короче. Значит, эти треугольники подобны с коэффициентом <span class="m">${fr('1', '2')}</span>, причём вершине <span class="m">A</span> соответствует <span class="m">${A1}</span>, ведь <span class="m">${B1}${C1} ∥ BC</span>.</p>
<p>Серединный перпендикуляр к <span class="m">BC</span> проходит через <span class="m">${A1}</span> и перпендикулярен <span class="m">${B1}${C1}</span> — это высота треугольника <span class="m">${A1}${B1}${C1}</span>. Поэтому <span class="m">O</span> — ортоцентр треугольника <span class="m">${A1}${B1}${C1}</span>. При подобии отрезок от вершины до ортоцентра переходит в такой же отрезок: <span class="m">AH</span> соответствует <span class="m">${A1}O</span>, и <span class="m">${A1}O = ${fr('AH', '2')}</span>. Оба отрезка перпендикулярны <span class="m">BC</span>, поэтому параллельны.</p>
<h3>Прямая Эйлера</h3>
${figE}
<div class="box"><div class="box-h">Теорема Эйлера</div>
<p>Точки <span class="m">O</span>, <span class="m">G</span>, <span class="m">H</span> лежат на одной прямой, точка <span class="m">G</span> — между <span class="m">H</span> и <span class="m">O</span>, и <span class="m">HG = 2 · GO</span>.</p></div>
<p><b>Доказательство.</b> Сравним треугольники <span class="m">AGH</span> и <span class="m">${A1}GO</span>. В них <span class="m">AG : G${A1} = 2 : 1</span> (свойство медиан), <span class="m">AH : ${A1}O = 2 : 1</span> (лемма), а углы <span class="m">HAG</span> и <span class="m">O${A1}G</span> равны как накрест лежащие при параллельных <span class="m">AH</span> и <span class="m">O${A1}</span>. Две стороны пропорциональны, углы между ними равны — треугольники подобны. Поэтому <span class="m">∠AGH = ∠${A1}GO</span>. Точки <span class="m">H</span> и <span class="m">O</span> лежат по разные стороны от прямой <span class="m">A${A1}</span>, поэтому эти равные углы — вертикальные, и <span class="m">H</span>, <span class="m">G</span>, <span class="m">O</span> лежат на одной прямой. Из подобия <span class="m">HG = 2 · GO</span>.</p>
<p>Эта прямая называется <b>прямой Эйлера</b>. В равностороннем треугольнике все три точки совпадают, а в равнобедренном лежат на оси симметрии.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>В прямоугольном треугольнике <span class="m">ABC</span> угол <span class="m">C</span> прямой, <span class="m">AC = 6</span>, <span class="m">BC = 8</span>. Высоты пересекаются в вершине прямого угла: <span class="m">H = C</span>. Центр <span class="m">O</span> — середина гипотенузы, <span class="m">AB = 10</span>, <span class="m">CO = 5</span>. Прямая Эйлера — это медиана <span class="m">CO</span>, и <span class="m">CG = ${fr('2', '3')} · 5 = ${fr('10', '3')}</span>.</p></div>
<h3>Окружность девяти точек</h3>
${figN}
<div class="box"><div class="box-h">Теорема</div>
<p>Середины сторон, основания высот и середины отрезков <span class="m">AH</span>, <span class="m">BH</span>, <span class="m">CH</span> — всего девять точек — лежат на одной окружности. Её центр <span class="m">N</span> — середина отрезка <span class="m">OH</span>, а радиус равен <span class="m">${fr('R', '2')}</span>.</p></div>
<p><b>Доказательство.</b> Пусть <span class="m">${A2}</span>, <span class="m">${B2}</span>, <span class="m">${C2}</span> — середины <span class="m">AH</span>, <span class="m">BH</span>, <span class="m">CH</span>. Средние линии дают: <span class="m">${C1}${B1} ∥ BC</span> (в треугольнике <span class="m">ABC</span>) и <span class="m">${B2}${C2} ∥ BC</span> (в <span class="m">HBC</span>); <span class="m">${C1}${B2} ∥ AH</span> (в <span class="m">ABH</span>) и <span class="m">${B1}${C2} ∥ AH</span> (в <span class="m">ACH</span>). Значит, <span class="m">${C1}${B1}${C2}${B2}</span> — параллелограмм со сторонами вдоль <span class="m">BC</span> и <span class="m">AH</span>. Так как <span class="m">AH ⊥ BC</span>, это прямоугольник: его диагонали <span class="m">${B1}${B2}</span> и <span class="m">${C1}${C2}</span> равны и делятся точкой пересечения пополам.</p>
<p>Точно так же <span class="m">${A1}${B1}${A2}${B2}</span> — прямоугольник (его стороны параллельны <span class="m">AB</span> и <span class="m">CH</span>). Итак, отрезки <span class="m">${A1}${A2}</span>, <span class="m">${B1}${B2}</span>, <span class="m">${C1}${C2}</span> равны и имеют общую середину <span class="m">N</span>: это диаметры одной окружности, и на ней лежат шесть точек.</p>
<p>Основание высоты <span class="m">D</span> лежит и на <span class="m">BC</span>, и на <span class="m">AH</span>, поэтому <span class="m">∠${A1}D${A2} = 90°</span>. Медиана прямоугольного треугольника <span class="m">${A1}D${A2}</span> равна половине гипотенузы, значит, <span class="m">D</span> лежит на окружности с диаметром <span class="m">${A1}${A2}</span>. Так же и два других основания высот.</p>
<p><b>Центр и радиус.</b> По лемме <span class="m">A${A2} = ${fr('AH', '2')} = O${A1}</span>, и эти отрезки параллельны и направлены одинаково: от <span class="m">A</span> к <span class="m">H</span> — так же, как от <span class="m">O</span> к <span class="m">${A1}</span>. Поэтому <span class="m">A${A2}${A1}O</span> — параллелограмм, и <span class="m">${A2}${A1} = AO = R</span>: радиус равен <span class="m">${fr('R', '2')}</span>. Так же <span class="m">${A2}H${A1}O</span> — параллелограмм, его диагонали <span class="m">${A2}${A1}</span> и <span class="m">OH</span> делятся пополам, поэтому <span class="m">N</span> — середина <span class="m">OH</span>.</p>
<p>Без доказательства, для кругозора: окружность девяти точек касается вписанной окружности и всех трёх вневписанных (теорема Фейербаха).</p>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь ортоцентр — вспоминай <span class="m">AH = 2 · O${A1}</span>. Видишь середины сторон и основания высот — ищи окружность девяти точек. Короткая запись для проверки: если поместить начало координат в <span class="m">O</span>, то вектор <span class="m">OH</span> равен сумме векторов <span class="m">OA</span>, <span class="m">OB</span> и <span class="m">OC</span>.</p></div>` },

      { id: 'tri-l8', title: 'Лемма о трезубце', mins: 14, html: `
<div class="box"><div class="box-h">Понадобится: вписанные углы</div><ul>
<li>Вписанный угол равен половине центрального угла, опирающегося на ту же дугу.</li>
<li>Вписанные углы, опирающиеся на одну дугу, равны. Равные вписанные углы опираются на равные дуги, а равные дуги стягиваются равными хордами.</li>
<li>Сумма противоположных углов вписанного четырёхугольника равна <span class="m">180°</span>.</li>
<li>Если точки <span class="m">X</span> и <span class="m">Y</span> лежат по одну сторону от прямой <span class="m">BC</span> и <span class="m">∠BXC = ∠BYC</span>, то точки <span class="m">B</span>, <span class="m">C</span>, <span class="m">X</span>, <span class="m">Y</span> лежат на одной окружности.</li>
</ul><p>Подробно эти факты разобраны в теме «Окружность». Здесь они — инструменты.</p></div>
<p><b>Вневписанная окружность</b> касается стороны <span class="m">BC</span> и продолжений сторон <span class="m">AB</span> и <span class="m">AC</span>. Её центр <span class="m">${Ia}</span> лежит на биссектрисе угла <span class="m">A</span> и на биссектрисах внешних углов при вершинах <span class="m">B</span> и <span class="m">C</span>.</p>
${figT}
<div class="box"><div class="box-h">Лемма о трезубце</div>
<p>Биссектриса угла <span class="m">A</span> второй раз пересекает описанную окружность треугольника <span class="m">ABC</span> в точке <span class="m">W</span>. Тогда <span class="m">WB = WC = WI = W${Ia}</span>.</p></div>
<p>Другими словами, точки <span class="m">B</span>, <span class="m">C</span>, <span class="m">I</span>, <span class="m">${Ia}</span> лежат на окружности с центром <span class="m">W</span>. Четыре равных отрезка из точки <span class="m">W</span> похожи на трезубец. Точка <span class="m">W</span> — середина дуги <span class="m">BC</span>, не содержащей <span class="m">A</span>, поэтому она лежит и на серединном перпендикуляре к <span class="m">BC</span>.</p>
<p><b>Доказательство.</b> 1) Вписанные углы <span class="m">BAW</span> и <span class="m">WAC</span> равны, поэтому равны хорды <span class="m">WB = WC</span>.</p>
<p>2) Углы <span class="m">WBC</span> и <span class="m">WAC</span> опираются на одну дугу, поэтому <span class="m">∠WBI = ∠WBC + ∠CBI = ${fr('∠A', '2')} + ${fr('∠B', '2')}</span>. Угол <span class="m">WIB</span> — внешний угол треугольника <span class="m">ABI</span>: <span class="m">∠WIB = ∠IAB + ∠IBA = ${fr('∠A', '2')} + ${fr('∠B', '2')}</span>. Углы равны, треугольник <span class="m">WBI</span> равнобедренный, <span class="m">WI = WB</span>.</p>
<p>3) Биссектрисы внутреннего и внешнего углов при вершине <span class="m">B</span> перпендикулярны: <span class="m">∠IB${Ia} = 90°</span>. В прямоугольном треугольнике <span class="m">IB${Ia}</span> точка <span class="m">W</span> лежит на гипотенузе, и <span class="m">∠WB${Ia} = 90° − ∠WBI = 90° − ∠WIB = ∠W${Ia}B</span>. Значит, <span class="m">W${Ia} = WB</span>, и <span class="m">W</span> — середина отрезка <span class="m">I${Ia}</span>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>В треугольнике <span class="m">ABC</span> угол <span class="m">A</span> прямой, <span class="m">BC = 10</span>. Биссектриса угла <span class="m">A</span> второй раз пересекает описанную окружность в точке <span class="m">W</span>. Найдите <span class="m">WI</span>.</p>
<p><b>Решение.</b> <span class="m">BC</span> — диаметр, <span class="m">W</span> — середина полуокружности, треугольник <span class="m">BWC</span> прямоугольный и равнобедренный: <span class="m">WB = ${fr('10', sq('2'))} = 5${sq('2')}</span>. По лемме <span class="m">WI = WB = 5${sq('2')}</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Есть центр вписанной окружности и описанная окружность — продли <span class="m">AI</span> до второго пересечения с окружностью. Окружность через <span class="m">B</span>, <span class="m">I</span>, <span class="m">C</span> имеет центр на описанной окружности — это частая скрытая подсказка. И обратно: чтобы доказать, что точка <span class="m">P</span> — центр вписанной окружности, достаточно проверить, что она лежит на отрезке <span class="m">AW</span> и <span class="m">WP = WB</span>.</p></div>` },

      { id: 'tri-l9', title: 'Изогональное сопряжение', mins: 16, html: `
<p>Этот приём объясняет, почему у треугольника так много замечательных точек: они связаны парами.</p>
${figIso}
<div class="box"><div class="box-h">Определение</div>
<p>Прямые <span class="m">AX</span> и <span class="m">AY</span> называют <b>изогональными</b>, если они симметричны относительно биссектрисы угла <span class="m">A</span>, то есть <span class="m">∠BAX = ∠YAC</span>.</p></div>
<h3>Высота и радиус</h3>
<p>В остроугольном треугольнике высота <span class="m">AD</span> и прямая <span class="m">AO</span> изогональны. Из прямоугольного треугольника <span class="m">ABD</span>: <span class="m">∠BAD = 90° − ∠B</span>. Центральный угол <span class="m">AOC</span> вдвое больше вписанного угла <span class="m">ABC</span>, то есть <span class="m">∠AOC = 2∠B</span>. Треугольник <span class="m">AOC</span> равнобедренный (<span class="m">OA = OC = R</span>), поэтому <span class="m">∠OAC = ${fr('180° − 2∠B', '2')}</span> <span class="m">= 90° − ∠B</span>.</p>
<h3>Лемма о расстояниях</h3>
<p>Обозначим через <span class="m">d(X, AB)</span> расстояние от точки <span class="m">X</span> до прямой <span class="m">AB</span>.</p>
<ul>
<li>Для всех точек <span class="m">X</span> одной прямой, проходящей через <span class="m">A</span>, отношение <span class="m">d(X, AB) : d(X, AC)</span> одно и то же: прямоугольные треугольники с общим острым углом подобны.</li>
<li>Для изогональной прямой это отношение <b>обратное</b>. Симметрия относительно биссектрисы меняет местами прямые <span class="m">AB</span> и <span class="m">AC</span> и переводит прямую <span class="m">AX</span> в <span class="m">AY</span>. Поэтому у образа точки <span class="m">X</span> расстояния до <span class="m">AB</span> и <span class="m">AC</span> меняются местами.</li>
</ul>
<h3>Главная теорема</h3>
<div class="box"><div class="box-h">Теорема</div>
<p>Пусть прямые <span class="m">AP</span>, <span class="m">BP</span>, <span class="m">CP</span> проходят через точку <span class="m">P</span>. Тогда прямые, изогональные им, тоже пересекаются в одной точке <span class="m">P*</span>. Её называют точкой, <b>изогонально сопряжённой</b> точке <span class="m">P</span>.</p></div>
<p><b>Доказательство.</b> Отразим <span class="m">P</span> относительно сторон: <span class="m">${Pa}</span>, <span class="m">${Pb}</span>, <span class="m">${Pc}</span> — образы относительно <span class="m">BC</span>, <span class="m">CA</span>, <span class="m">AB</span>. Тогда <span class="m">A${Pb} = AP = A${Pc}</span>, и треугольник <span class="m">${Pc}A${Pb}</span> равнобедренный. Пусть <span class="m">∠BAP = φ</span>. Тогда <span class="m">∠${Pc}AB = φ</span> и <span class="m">∠CA${Pb} = ∠PAC = ∠A − φ</span>, так что <span class="m">∠${Pc}A${Pb} = 2∠A</span>. Его биссектриса — это серединный перпендикуляр к <span class="m">${Pb}${Pc}</span>, и она образует со стороной <span class="m">AB</span> угол <span class="m">∠A − φ</span>. Значит, она изогональна прямой <span class="m">AP</span>.</p>
<p>Итак, три изогональные прямые — серединные перпендикуляры к сторонам треугольника <span class="m">${Pa}${Pb}${Pc}</span>. Они пересекаются в центре его описанной окружности. (Точки <span class="m">${Pa}</span>, <span class="m">${Pb}</span>, <span class="m">${Pc}</span> лежат на одной прямой, только когда <span class="m">P</span> лежит на описанной окружности треугольника <span class="m">ABC</span>.)</p>
<div class="box"><div class="box-h">Пары сопряжённых точек</div><ul>
<li><span class="m">I</span> сопряжена сама себе: биссектрисы изогональны сами себе.</li>
<li><span class="m">H</span> и <span class="m">O</span> сопряжены: высоты изогональны прямым <span class="m">AO</span>, <span class="m">BO</span>, <span class="m">CO</span>.</li>
<li>Прямые, изогональные медианам, называются <b>симедианами</b>. Точка их пересечения <span class="m">K</span> — <b>точка Лемуана</b>, она сопряжена точке <span class="m">G</span>.</li>
</ul></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Из леммы о расстояниях: у сопряжённых точек <span class="m">P</span> и <span class="m">P*</span> произведение расстояний до стороны одно и то же для всех трёх сторон: <span class="m">d(P, AB) · d(P*, AB)</span> <span class="m">= d(P, AC) · d(P*, AC)</span> <span class="m">= d(P, BC) · d(P*, BC)</span>. А если в условии два угла равны «крест-накрест», например <span class="m">∠BAP = ∠QAC</span> и <span class="m">∠ABP = ∠QBC</span>, — точки <span class="m">P</span> и <span class="m">Q</span> изогонально сопряжены.</p></div>` }
    ],

    problems: [
      // Уровень 4 — глубокий
      { id: 'tri-41', lvl: 4, r: 1960, type: 'num', q: `Расстояние от центра O описанной окружности треугольника ABC до прямой BC равно 7. Найдите расстояние от вершины A до ортоцентра H этого треугольника.`, a: ['14'],
        hints: [`Перпендикуляр из O на BC попадает в середину ${A1} стороны BC: точка O лежит на серединном перпендикуляре.`, `Вспомни главную лемму урока «Прямая Эйлера и окружность девяти точек».`],
        sol: `Перпендикуляр из O на BC — часть серединного перпендикуляра, поэтому он попадает в середину ${A1} стороны BC, и O${A1} = 7. По главной лемме AH = 2 · O${A1} = 14. Ответ: 14.` },
      { id: 'tri-42', lvl: 4, r: 1970, type: 'num', q: `В треугольнике ABC расстояние между центром O описанной окружности и ортоцентром H равно 12. Найдите расстояние от точки пересечения медиан G до центра N окружности девяти точек.`, a: ['2'],
        hints: [`Точка G лежит на отрезке OH, и HG = 2 · GO. Найди OG.`, `Центр окружности девяти точек — середина отрезка OH.`],
        sol: `По теореме Эйлера G лежит на отрезке OH и OG = ${fr('1', '3')} · OH = 4. Центр N — середина OH, поэтому ON = 6. Обе точки лежат на отрезке OH, так что GN = 6 − 4 = 2. Ответ: 2.` },
      { id: 'tri-43', lvl: 4, r: 1980, type: 'num', q: `В треугольнике ABC угол B равен 75°, угол C равен 45°. AD — высота, O — центр описанной окружности. Найдите угол DAO (в градусах).`, a: ['30'],
        hints: [`Угол BAD найдётся из прямоугольного треугольника ABD.`, `Высота и прямая AO изогональны: ∠OAC = ∠BAD.`, `∠A = 180° − 75° − 45° = 60°.`],
        sol: `Из прямоугольного треугольника ABD: ∠BAD = 90° − 75° = 15°. Треугольник остроугольный, и прямая AO изогональна высоте: ∠OAC = 90° − ∠B = 15° (центральный угол AOC равен 150°, треугольник AOC равнобедренный). ∠A = 60°, поэтому ∠DAO = 60° − 15° − 15° = 30°. Заметь: ответ равен ∠B − ∠C, и так бывает всегда. Ответ: 30.` },
      { id: 'tri-44', lvl: 4, r: 1990, type: 'num', q: `В треугольнике ABC угол A равен 120°, BC = 7. Найдите расстояние между центром I вписанной окружности и центром ${Ia} вневписанной окружности, касающейся стороны BC.`, a: ['14'],
        hints: [`Пусть биссектриса угла A второй раз пересекает описанную окружность в точке W. По лемме о трезубце WI = WB = W${Ia}.`, `Четырёхугольник ABWC вписанный. Чему равен угол BWC и какой получается треугольник BWC?`],
        sol: `Пусть W — вторая точка пересечения биссектрисы угла A с описанной окружностью. Во вписанном четырёхугольнике ABWC угол BWC равен 180° − 120° = 60°, а WB = WC. Значит, треугольник BWC равносторонний и WB = BC = 7. По лемме о трезубце W — середина отрезка I${Ia} и WI = W${Ia} = WB = 7, поэтому I${Ia} = 14. Ответ: 14.` },
      { id: 'tri-45', lvl: 4, r: 2000, type: 'num', q: `Стороны треугольника ABC: AB = 13, BC = 14, CA = 15. Найдите радиус окружности, проходящей через основания трёх его высот.`, a: ['65/16', '4.0625'],
        hints: [`Основания высот лежат на окружности девяти точек, её радиус равен ${fr('R', '2')}.`, `Найди R в координатах: B = (0; 0), C = (14; 0), A = (5; 12). Проверь, что AB = 13 и AC = 15.`, `Центр O = (7; y) лежит на серединном перпендикуляре к BC. Приравняй OB и OA.`],
        sol: `Основания высот лежат на окружности девяти точек, её радиус равен ${fr('R', '2')}. Поставим B = (0; 0), C = (14; 0), A = (5; 12): тогда AB = 13, AC = 15. Центр O = (7; y). Из OB = OA: 49 + y<sup>2</sup> = 4 + (12 − y)<sup>2</sup>, откуда 24y = 99 и y = ${fr('33', '8')}. Тогда R<sup>2</sup> = 49 + ${fr('1089', '64')} = ${fr('4225', '64')}, R = ${fr('65', '8')}. Искомый радиус ${fr('65', '16')} = 4,0625. Ответ: ${fr('65', '16')}.` },
      { id: 'tri-46', lvl: 4, r: 2010, type: 'proof', q: `I — центр вписанной окружности треугольника ABC, причём AB ≠ AC. Окружность, проходящая через точки B, I и C, второй раз пересекает прямую AB в точке P. Докажите, что AP = AC.${fig46}`,
        hints: [`По лемме о трезубце центр окружности BIC — точка W, в которой прямая AI второй раз пересекает описанную окружность.`, `Отрази точку C относительно прямой AI. Куда попадёт её образ? Почему он лежит на окружности с центром W?`],
        sol: `Пусть W — вторая точка пересечения прямой AI с описанной окружностью треугольника ABC. По лемме о трезубце окружность через B, I, C имеет центр W. Отразим C относительно прямой AI, получим точку C'. Прямая AI — биссектриса угла A, поэтому луч AC переходит в луч AB: точка C' лежит на луче AB и AC' = AC. Точка W лежит на оси симметрии, поэтому WC' = WC, то есть C' лежит на окружности BIC. Так как AC ≠ AB, точка C' отлична от B. Прямая пересекает окружность не более чем в двух точках, значит, C' = P и AP = AC.`,
        rubric: [[2, `Центр окружности BIC — точка W (лемма о трезубце)`], [3, `Симметрия относительно AI: C′ на луче AB, AC′ = AC, WC′ = WC`], [2, `C′ ≠ B, поэтому C′ — вторая точка пересечения P`]] },
      { id: 'tri-47', lvl: 4, r: 2030, type: 'proof', q: `Треугольник ABC не равносторонний. Докажите, что его прямая Эйлера проходит через вершину A тогда и только тогда, когда AB = AC или ∠A = 90°.`,
        hints: [`В одну сторону: если AB = AC, замечательные точки лежат на оси симметрии; если ∠A = 90°, то H = A.`, `В другую: прямая Эйлера проходит через G. Если она проходит ещё и через A, то это прямая медианы A${A1}.`, `Точка O лежит и на медиане, и на серединном перпендикуляре к BC. Когда у этих прямых больше одной общей точки?`],
        sol: `Треугольник не равносторонний, поэтому O ≠ H, и прямая Эйлера определена. Если AB = AC, то O, G, H лежат на оси симметрии, а она проходит через A. Если ∠A = 90°, то высоты пересекаются в вершине A, то есть H = A. Обратно, пусть прямая Эйлера проходит через A. Она проходит и через G, причём G ≠ A, поэтому это прямая медианы A${A1}. Значит, O лежит на прямой A${A1}. Но O лежит и на серединном перпендикуляре к BC, который проходит через ${A1}. Если эти прямые совпадают, медиана перпендикулярна BC, и AB = AC. Если нет, их единственная общая точка — ${A1}, и O = ${A1}. Тогда BC — диаметр описанной окружности, медиана A${A1} равна половине BC, и ∠A = 90°.`,
        rubric: [[2, `Достаточность: оба случая`], [2, `Прямая Эйлера совпадает с медианой A${A1}`], [2, `O на медиане и на серединном перпендикуляре: прямые совпадают или O = ${A1}`], [1, `Выводы AB = AC и ∠A = 90°`]] },
      { id: 'tri-48', lvl: 4, r: 2050, type: 'proof', q: `H — ортоцентр треугольника ABC, P — произвольная точка его описанной окружности. Докажите, что середина отрезка HP лежит на окружности девяти точек.`,
        hints: [`Центр N окружности девяти точек — середина OH, а её радиус равен ${fr('R', '2')}.`, `Рассмотри треугольник OHP и его среднюю линию.`],
        sol: `Пусть M — середина HP, а N — середина HO, то есть центр окружности девяти точек. В треугольнике HOP отрезок NM — средняя линия, поэтому NM = ${fr('OP', '2')} = ${fr('R', '2')}. Значит, M лежит на окружности с центром N и радиусом ${fr('R', '2')} — на окружности девяти точек. Если точки O, H, P лежат на одной прямой, равенство NM = ${fr('OP', '2')} тоже верно: N и M — середины отрезков HO и HP, отложенных от точки H по одной прямой. Вывод: окружность девяти точек получается из описанной окружности сжатием к точке H в 2 раза.`,
        rubric: [[2, `Использованы центр N (середина OH) и радиус R/2`], [4, `NM — средняя линия треугольника HOP, NM = R/2`], [1, `Вырожденный случай или итоговый вывод`]] },

      // Уровень 5 — глубокий
      { id: 'tri-49', lvl: 5, r: 2100, type: 'proof', q: `В остроугольном треугольнике ABC угол A равен 60°. Докажите, что точки B, C, O, H и I лежат на одной окружности, и найдите её центр.`,
        hints: [`Найди углы BOC, BHC и BIC.`, `Для угла BHC: пусть B${B1} и C${C1} — высоты. В четырёхугольнике A${C1}H${B1} два угла прямые.`, `Центр окружности через B, I, C даёт лемма о трезубце.`],
        sol: `Центральный угол BOC вдвое больше вписанного угла A: ∠BOC = 120°. Пусть B${B1} и C${C1} — высоты. В четырёхугольнике A${C1}H${B1} углы при вершинах ${B1} и ${C1} прямые, поэтому ∠${B1}H${C1} = 360° − 90° − 90° − 60° = 120°, и ∠BHC = 120° как вертикальный. Наконец, ∠BIC = 90° + ${fr('∠A', '2')} = 120°. Треугольник остроугольный, поэтому O и H лежат внутри него, и точки O, H, I находятся по одну сторону от BC. Из каждой из них отрезок BC виден под углом 120°, значит, B, C, O, H, I лежат на одной окружности. По лемме о трезубце её центр — точка W, в которой биссектриса угла A второй раз пересекает описанную окружность, то есть середина дуги BC.`,
        rubric: [[2, `∠BOC = 120°`], [2, `∠BHC = 120°`], [1, `∠BIC = 120°`], [1, `Точки по одну сторону от BC, вывод`], [1, `Центр — точка W`]] },
      { id: 'tri-50', lvl: 5, r: 2180, type: 'proof', q: `H — ортоцентр остроугольного треугольника ABC, ${A1} — середина стороны BC. Докажите, что точки, симметричные H относительно прямой BC и относительно точки ${A1}, лежат на описанной окружности треугольника ABC.`,
        hints: [`Сначала докажи, что ∠BHC = 180° − ∠A: в четырёхугольнике с вершинами A, H и основаниями двух высот два угла прямые.`, `Пусть A' — точка окружности, диаметрально противоположная A. Углы ABA' и ACA' прямые.`, `Докажи, что BHCA' — параллелограмм.`],
        sol: `Пусть B${B1} и C${C1} — высоты. В четырёхугольнике A${C1}H${B1} два прямых угла, поэтому ∠BHC = ∠${B1}H${C1} = 180° − ∠A. 1) Пусть H' симметрична H относительно BC. Тогда ∠BH'C = ∠BHC = 180° − ∠A, и точка H' лежит по другую сторону от BC, чем A. Сумма противоположных углов четырёхугольника ABH'C равна 180°, значит, он вписанный, и H' лежит на описанной окружности. 2) Пусть A' — точка окружности, диаметрально противоположная A. Углы ABA' и ACA' опираются на диаметр, поэтому A'B ⊥ AB и A'C ⊥ AC. Но и CH ⊥ AB, BH ⊥ AC, значит, A'B ∥ CH и A'C ∥ BH: BHCA' — параллелограмм. Его диагонали HA' и BC делятся точкой пересечения пополам, то есть ${A1} — середина HA'. Значит, точка, симметричная H относительно ${A1}, — это A', и она лежит на окружности.`,
        rubric: [[1, `∠BHC = 180° − ∠A`], [2, `Симметрия относительно BC и признак вписанного четырёхугольника`], [3, `BHCA′ — параллелограмм`], [1, `${A1} — середина HA′, вывод`]] },
      { id: 'tri-51', lvl: 5, r: 2260, type: 'proof', q: `Прямая, симметричная медиане AM треугольника ABC относительно биссектрисы угла A, пересекает сторону BC в точке D. Такая прямая называется симедианой. Докажите, что BD : DC = AB<sup>2</sup> : AC<sup>2</sup>.`,
        hints: [`У треугольников ABD и ADC общая высота из A, поэтому BD : DC равно отношению их площадей. А площади можно записать через расстояния от D до прямых AB и AC.`, `Для середины M: площади ABM и AMC равны, то есть AB · d(M, AB) = AC · d(M, AC).`, `По лемме о расстояниях у изогональной прямой отношение расстояний обратное.`],
        sol: `Через d(X, AB) обозначим расстояние от X до прямой AB. У треугольников ABD и ADC общая высота из A, поэтому ${fr('BD', 'DC')} = ${fr('S<sub>ABD</sub>', 'S<sub>ADC</sub>')} = ${fr('AB · d(D, AB)', 'AC · d(D, AC)')}. Медиана делит площадь пополам: AB · d(M, AB) = AC · d(M, AC), то есть ${fr('d(M, AB)', 'd(M, AC)')} = ${fr('AC', 'AB')}. Прямая AD изогональна AM, и по лемме о расстояниях ${fr('d(D, AB)', 'd(D, AC)')} = ${fr('AB', 'AC')}. Подставляем: ${fr('BD', 'DC')} = ${fr('AB', 'AC')} · ${fr('AB', 'AC')} = ${fr('AB<sup>2</sup>', 'AC<sup>2</sup>')}.`,
        rubric: [[2, `BD : DC через площади и расстояния`], [2, `Отношение расстояний для точки M`], [2, `Обратное отношение для изогональной прямой`], [1, `Вывод`]] },
      { id: 'tri-52', lvl: 5, r: 2320, type: 'proof', q: `A${A1}, B${B1}, C${C1} — высоты остроугольного треугольника ABC, H — ортоцентр. Докажите, что H — центр окружности, вписанной в треугольник ${A1}${B1}${C1}.`,
        hints: [`Точки ${A1} и ${B1} видят отрезок CH под прямым углом, поэтому лежат на окружности с диаметром CH. Какие вписанные углы в ней равны?`, `Из этой окружности ∠H${B1}${A1} = ∠HC${A1}. Докажи, что это 90° − ∠B.`, `Так же с окружностью на диаметре AH найди угол H${B1}${C1}.`],
        sol: `Углы H${A1}C и H${B1}C прямые, поэтому ${A1} и ${B1} лежат на окружности с диаметром CH. Вписанные углы H${B1}${A1} и HC${A1} опираются на одну дугу: ∠H${B1}${A1} = ∠HC${A1} = ∠${C1}CB = 90° − ∠B (из прямоугольного треугольника B${C1}C). Точно так же ${B1} и ${C1} лежат на окружности с диаметром AH, и ∠H${B1}${C1} = ∠HA${C1} = ∠${A1}AB = 90° − ∠B. Значит, ${B1}H — биссектриса угла ${A1}${B1}${C1}. Аналогично ${A1}H и ${C1}H — биссектрисы двух других углов треугольника ${A1}${B1}${C1}. Поэтому H — точка пересечения его биссектрис, то есть центр вписанной окружности.`,
        rubric: [[2, `Окружности с диаметрами CH и AH`], [2, `∠H${B1}${A1} = 90° − ∠B`], [2, `∠H${B1}${C1} = 90° − ∠B`], [1, `Аналогично для других вершин, вывод`]] },
      { id: 'tri-53', lvl: 5, r: 2360, type: 'num', q: `Катеты прямоугольного треугольника равны 3 и 4. Найдите расстояние от точки Лемуана (точки пересечения симедиан) до гипотенузы.`, a: ['6/5', '1.2'],
        hints: [`Точка Лемуана K изогонально сопряжена точке G. Площади треугольников GBC, GCA, GAB равны, поэтому расстояния от G до сторон обратно пропорциональны сторонам.`, `У сопряжённых точек произведения расстояний до сторон одинаковы. Значит, расстояния от K до сторон пропорциональны сторонам: 3t, 4t, 5t.`, `Сложи площади треугольников, на которые K делит исходный: ${fr('1', '2')}(3 · 3t + 4 · 4t + 5 · 5t) = 6.`],
        sol: `Площадь треугольника равна 6. Треугольники GBC, GCA, GAB равновелики, поэтому произведение стороны на расстояние от G до неё одинаково для всех сторон: расстояния от G обратно пропорциональны сторонам. У изогонально сопряжённых точек G и K произведения расстояний до каждой стороны одинаковы, поэтому расстояния от K до сторон 3, 4, 5 равны 3t, 4t, 5t. Сумма площадей треугольников с вершиной K равна площади всего треугольника: ${fr('1', '2')}(9t + 16t + 25t) = 6, t = ${fr('6', '25')}. Расстояние до гипотенузы 5t = ${fr('6', '5')}. Проверка: в прямоугольном треугольнике симедиана из вершины прямого угла — это высота, а K — середина высоты: ${fr('12', '5')} : 2 = ${fr('6', '5')}. Ответ: ${fr('6', '5')} = 1,2.` },
      { id: 'tri-54', lvl: 5, r: 2420, type: 'proof', q: `Точки P и Q внутри треугольника ABC изогонально сопряжены. Докажите, что шесть проекций точек P и Q на стороны треугольника лежат на одной окружности с центром в середине отрезка PQ.`,
        hints: [`Пусть ${Pc}, ${Qc} — проекции P и Q на AB, M — середина PQ. Проекция M на AB — середина отрезка ${Pc}${Qc}. Почему?`, `Докажи, что A${Pc} · A${Qc} = A${Pb} · A${Qb}: сравни прямоугольные треугольники AP${Pc} и AQ${Qb}, затем AQ${Qc} и AP${Pb}.`, `Из этого равенства точки ${Pc}, ${Qc}, ${Pb}, ${Qb} лежат на одной окружности. Где её центр?`],
        sol: `Пусть ${Pa}, ${Pb}, ${Pc} — проекции P на BC, CA, AB; ${Qa}, ${Qb}, ${Qc} — проекции Q; M — середина PQ. 1) В трапеции P${Pc}${Qc}Q боковые стороны P${Pc} и Q${Qc} перпендикулярны AB, поэтому проекция точки M на AB — середина ${Pc}${Qc}. Значит, M лежит на серединном перпендикуляре к ${Pc}${Qc}. Так же M лежит на серединных перпендикулярах к ${Pb}${Qb} и ${Pa}${Qa}. 2) Прямоугольные треугольники AP${Pc} и AQ${Qb} подобны: ∠PA${Pc} = ∠BAP = ∠QAC = ∠QA${Qb}. Поэтому ${fr('A' + Pc, 'AP')} = ${fr('A' + Qb, 'AQ')}. Так же из подобия треугольников AQ${Qc} и AP${Pb}: ${fr('A' + Qc, 'AQ')} = ${fr('A' + Pb, 'AP')}. Перемножив, получаем A${Pc} · A${Qc} = A${Pb} · A${Qb}. 3) Значит, треугольники A${Pc}${Pb} и A${Qb}${Qc} подобны (угол A общий, ${fr('A' + Pc, 'A' + Qb)} = ${fr('A' + Pb, 'A' + Qc)}), откуда ∠A${Pc}${Pb} = ∠A${Qb}${Qc}, и четыре точки ${Pc}, ${Qc}, ${Pb}, ${Qb} лежат на одной окружности. Её центр лежит на серединных перпендикулярах к хордам ${Pc}${Qc} и ${Pb}${Qb}. Эти прямые перпендикулярны AB и AC, поэтому пересекаются в одной точке, и это M. Итак, M${Pc} = M${Qc} = M${Pb} = M${Qb}. 4) То же рассуждение для вершины B даёт M${Pc} = M${Qc} = M${Pa} = M${Qa}. Все шесть проекций удалены от M на одно расстояние.`,
        rubric: [[2, `M лежит на серединных перпендикулярах (трапеция)`], [2, `A${Pc} · A${Qc} = A${Pb} · A${Qb} через подобие`], [2, `Четыре проекции на одной окружности, её центр — M`], [1, `Вывод для всех шести точек`]] },
      { id: 'tri-55', lvl: 5, r: 2490, type: 'proof', q: `В треугольнике ABC, который не является равносторонним, AB + AC = 2BC. Докажите, что прямая OI перпендикулярна биссектрисе AI (O и I — центры описанной и вписанной окружностей).`,
        hints: [`Пусть D — точка пересечения AI с BC, а W — вторая точка пересечения AI с описанной окружностью. Найди AI : ID, применив свойство биссектрисы дважды.`, `Треугольники WBD и WAB подобны. Отсюда WB<sup>2</sup> = WD · WA, а WB = WI по лемме о трезубце.`, `Обозначь ID = t и найди WD. Получится, что I — середина хорды AW.`],
        sol: `Пусть a = BC, b = CA, c = AB; по условию b + c = 2a. Биссектриса AI пересекает BC в точке D и описанную окружность — в точке W. 1) По свойству биссектрисы BD = ${fr('ac', 'b + c')}. Отрезок BI — биссектриса треугольника ABD, поэтому ${fr('AI', 'ID')} = ${fr('AB', 'BD')} = ${fr('b + c', 'a')} = 2. 2) Треугольники WBD и WAB подобны: угол W общий, а ∠WBD = ∠WBC = ∠WAC = ∠WAB. Отсюда ${fr('WB', 'WD')} = ${fr('WA', 'WB')}, то есть WB<sup>2</sup> = WD · WA, и по лемме о трезубце WB = WI. 3) Пусть ID = t, тогда AI = 2t; пусть WD = u. Точки идут в порядке A, I, D, W, поэтому WI = t + u, WA = 3t + u и (t + u)<sup>2</sup> = u(3t + u). Отсюда t<sup>2</sup> = tu и u = t. Значит, WI = 2t = AI: точка I — середина хорды AW. 4) Треугольник AOW равнобедренный (OA = OW = R), и его медиана OI перпендикулярна основанию AW. Точки O и I различны, потому что треугольник не равносторонний.`,
        rubric: [[2, `AI : ID = 2`], [2, `WB<sup>2</sup> = WD · WA и WB = WI`], [2, `Вычисление: I — середина AW`], [1, `OI ⊥ AW`]] }
    ]
  });
})();

